def parse_json(json_str):
    def parse_value(value_str):
        value_str = value_str.strip()
        if value_str == 'true':
            return True
        elif value_str == 'false':
            return False
        elif value_str == 'null':
            return None
        elif value_str[0] == '"':
            return value_str[1:-1].replace('\\"', '"').replace('\\n', '\n')
        elif value_str.isdigit():
            return int(value_str)
        elif value_str.startswith('-') and value_str[1:].isdigit():
            return -int(value_str[1:])
        elif '.' in value_str:
            return float(value_str)
        else:
            raise ValueError("Invalid JSON value")

    def parse_object(obj_str):
        obj_str = obj_str.strip()
        if obj_str[0] != '{' or obj_str[-1] != '}':
            raise ValueError("Invalid JSON object")
        obj_str = obj_str[1:-1].strip()
        if not obj_str:
            return {}
        result = {}
        pairs = obj_str.split(',')
        for pair in pairs:
            key, value = pair.strip().split(':')
            result[key.strip('"')] = parse_value(value)
        return result

    def parse_array(arr_str):
        arr_str = arr_str.strip()
        if arr_str[0] != '[' or arr_str[-1] != ']':
            raise ValueError("Invalid JSON array")
        arr_str = arr_str[1:-1].strip()
        if not arr_str:
            return []
        result = []
        elements = arr_str.split(',')
        for element in elements:
            result.append(parse_value(element.strip()))
        return result

    json_str = json_str.strip()
    if json_str.startswith('{'):
        return parse_object(json_str)
    elif json_str.startswith('['):
        return parse_array(json_str)
    else:
        return parse_value(json_str)

