                depth -= 1
            elif char == ',' and depth == 0:
                result.append(parse_value(item.strip()))
                item = ""
            else:
                item += char
        if item:
            result.append(parse_value(item.strip()))
        return result

    json_str = json_str.strip()
    if json_str[0] == '{':
        return parse_object(json_str[1:-1])
    elif json_str[0] == '[':
