import re

def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) if '.' in value else int(value)
        elif value.startswith('"') and value.endswith('"'):
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n')
        else:
            raise ValueError("Invalid JSON value")

    def parse_object():
        obj = {}
        json_str = json_str.strip()
        if json_str[0] != '{':
            raise ValueError("Expected '{'")
        json_str = json_str[1:]
        while True:
            key, json_str = parse_string(), json_str.strip()
            if json_str[0] != ':':
                raise ValueError("Expected ':'")
            json_str = json_str[1:].strip()
            value, json_str = parse_value(json_str), json_str.strip()
            obj[key] = value
            if json_str[0] == '}':
                return obj, json_str[1:]
            elif json_str[0] != ',':
                raise ValueError("Expected ',' or '}'")
            json_str = json_str[1:].strip()

    def parse_array():
        arr = []
        json_str = json_str.strip()
        if json_str[0] != '[':
            raise ValueError("Expected '['")
        json_str = json_str[1:]
        while True:
            value, json_str = parse_value(json_str), json_str.strip()
            arr.append(value)
            if json_str[0] == ']':
                return arr, json_str[1:]
            elif json_str[0] != ',':
                raise ValueError("Expected ',' or ']'")
            json_str = json_str[1:].strip()

    def parse_string():
        if json_str[0] != '"':
